"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[6280],{9690(a){a.exports=JSON.parse('{"title":"Edge \ub7f0\ud0c0\uc784\uc758 \uc2dc\ub300\uac00 \uc544\uc9c1 \uc624\uc9c0 \uc54a\uc558\ub2e4","date":"2024-05-02","coverUrl":null,"html":"<h2 data-notion-block-id=\\"15dd44ad-c3a4-4cbe-be4c-703e7927011d\\" id=\\"15dd44ad-c3a4-4cbe-be4c-703e7927011d\\">Edge \ub7f0\ud0c0\uc784\uc758 \uc2dc\ub300\uac00 \uc544\uc9c1 \uc624\uc9c0 \uc54a\uc558\ub2e4.</h2><a href=\\"https://youtu.be/lAGE-k1Zfrg?si=5SP4hyoFkixTsh-y\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://youtu.be/lAGE-k1Zfrg?si=5SP4hyoFkixTsh-y</a><p data-notion-block-id=\\"da9ba393-ff3f-4cfa-9ef6-938c084d64ff\\"><b>\uc2ec\uc724\uc12d</b>: Vercel\uc758 \uc81c\ud488\uc744 Edge \ub80c\ub354\ub9c1\uc5d0\uc11c Node.js \ub80c\ub354\ub9c1\uc73c\ub85c \ub3cc\ub838\ub2e4\ub294 \uc18c\uc2dd\uc785\ub2c8\ub2e4(<a href=\\"https://x.com/leeerob/status/1780705942734331983\\">\ud2b8\uc717 \ubc1c\ud45c</a>). V0 \uc81c\ud488\uc744 \ud14c\uc2a4\ud2b8\ud558\uba74\uc11c Edge \ub80c\ub354\ub9c1\uc774 \uc544\uc9c1 \ub370\uc774\ud130\ubca0\uc774\uc2a4 \ubb38\uc81c\uc640 \ucf5c\ub4dc \uc2a4\ud0c0\ud2b8 \ubb38\uc81c\uac00 \uc644\uc804\ud788 \ud574\uacb0\ub418\uc9c0 \uc54a\uc558\uc74c\uc744 \ud2b8\uc704\ud130\ub85c \uc54c\ub838\uace0, \uc704 \uc601\uc0c1\uc740 Edge \ub7f0\ud0c0\uc784\uacfc \uadf8 \ud2b8\uc717\uc5d0 \ub300\ud55c \uc124\uba85\uc785\ub2c8\ub2e4. \ubb3c\ub860 <a href=\\"https://ones-to-watch.ethansup.net/news/post/5c2a8faf-fd60-46cd-9bd2-d18b226e996f#bc31c13c-d967-46a5-88e2-6b487f1031d1\\">\ud6a8\uc728\uc801\uc778 \ub7f0\ud0c0\uc784\uc744 \uace0\ubbfc\ud558\uac70\ub098</a> Edge Database\ub97c \ubaa9\ud45c\ub85c \uc11c\ube44\uc2a4\ub97c \ud558\ub294 \uacf3\ub3c4 \uc788\uc2b5\ub2c8\ub2e4(ex. <a href=\\"https://turso.tech/\\">Turso</a>). \ud558\uc9c0\ub9cc \uc544\uc9c1\uc740 \uc774\ub97c \uc218\ub3c4 \uc788\uaca0\ub124\uc694.</p><h2 data-notion-block-id=\\"277922fc-4a4a-4563-bb7f-8a4529b28a54\\" id=\\"277922fc-4a4a-4563-bb7f-8a4529b28a54\\">\ud504\ub860\ud2b8\uc5d4\ub4dc \uc804\ubc18 \uc0b4\ud3b4\ubcf4\uae30</h2><a href=\\"https://frontendmasters.com/guides/front-end-handbook/2024/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://frontendmasters.com/guides/front-end-handbook/2024/</a><p data-notion-block-id=\\"a62cb83a-c6d7-4f83-b9dc-057a0baa2e54\\"><b>\uc2ec\uc724\uc12d</b>: \uc608\uc804\uc5d0 \uacf5\uc720\ud588\ub358 <a href=\\"https://ones-to-watch.ethansup.net/news/post/30480561-d12b-484b-9886-1eafeb5b6d35#44319358-d78c-4227-950b-e11083ea5513\\">\ud504\ub860\ud2b8\uc5d4\ub4dc\uc640 \uacfc\uac70\uc640 \ud604\uc7ac</a>(<a href=\\"https://ykss.netlify.app/translation/navigating_the_future_of_frontend/\\">\ud55c\uad6d\uc5b4 \ubc88\uc5ed</a>)\uc740 \uc5b4\ub290\uc815\ub3c4 \uc6f9\uc744 \uacbd\ud5d8\ud574\ubcf8 \uc0ac\ub78c\uc744 \uc704\ud55c \uac83\uc774\uc600\ub2e4\uba74, \uc704\uc758 \ucc45\uc740 \uc6f9\uc744 \uc785\ubb38\ud558\ub294 \uc0ac\ub78c\uc5d0\uac8c \uae30\ubcf8\uacfc \uac04\ub2e8\ud55c \uae30\uc220\ub4e4\uc744 \uc18c\uac1c\ud558\ub294 \ucc45\uc785\ub2c8\ub2e4. \uaf2d \ubcf4\uc168\uc73c\uba74 \uc88b\uaca0\ub124\uc694.</p><h2 data-notion-block-id=\\"c47cfa2f-71c7-4c05-b82a-c6d5674eb9dd\\" id=\\"c47cfa2f-71c7-4c05-b82a-c6d5674eb9dd\\">DOM\uc758 \ub3d9\uc791\uacfc \ud504\ub808\uc784\uc6cc\ud06c\uc758 \ub3d9\uc791</h2><a href=\\"https://jakearchibald.com/2024/attributes-vs-properties/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://jakearchibald.com/2024/attributes-vs-properties/</a><p data-notion-block-id=\\"9c2e236c-59b8-4061-9aa7-e56a7ca21969\\">\uc18d\uc131\uc5d0 \ub300\ud55c DOM\uc758 \ub3d9\uc791, \uadf8\ub9ac\uace0 \ud504\ub808\uc784\uc6cc\ud06c\uac00 \uc774\ub97c \uc5b4\ub5bb\uac8c \ucc98\ub9ac\ud558\ub294\uc9c0\uc5d0 \ub300\ud55c \uae00\uc785\ub2c8\ub2e4. DOM\uc5d0\uc11c\uc758 \uc18d\uc131\uc774 \uc5b4\ub5bb\uac8c \ub3d9\uc791\ud558\ub294\uc9c0 \uac04\ub2e8\ud558\uac8c \uc124\uba85\ub418\uc5b4 \uc788\uc73c\ub2c8 \uac00\ubccd\uac8c \ubcfc \uc218 \uc788\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"613b0b37-a685-4b22-acfc-2b1d3f9caa20\\" id=\\"613b0b37-a685-4b22-acfc-2b1d3f9caa20\\">ESLint 9 \ucd9c\uc2dc\uc640 Prettier\uc758 \uad00\uacc4\uc124\uc815</h2><a href=\\"https://eslint.org/blog/2023/10/flat-config-rollout-plans/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://eslint.org/blog/2023/10/flat-config-rollout-plans/</a><a href=\\"https://eslint.org/blog/2023/10/deprecating-formatting-rules/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://eslint.org/blog/2023/10/deprecating-formatting-rules/</a><p data-notion-block-id=\\"64412055-236e-4a10-8f31-2fb52d78e9b5\\"><b>\uc2ec\uc724\uc12d</b>: \ubc30\ub2ec\uc758 \ubbfc\uc871\uc5d0\uc11c <a href=\\"https://techblog.woowahan.com/15903/?ref=codenary\\">\uacf5\uc720 config\ub9cc\ub4e4\uae30</a>\ub97c \ube14\ub85c\uadf8\uc5d0 \uacf5\uc720\ud588\uae38\ub798 \uc0dd\uac01\ub09c ESLint 9 \ucd9c\uc2dc\uc640 \ud568\uaed8 Flat Config \ub3c4\uc785, \ud3ec\ub9e4\ud305 \uad00\ub828 \ub8f0 \uc81c\uac70 \uacf5\uc9c0\ub97c \uac00\uc838\uc654\uc2b5\ub2c8\ub2e4. ESLint \ud300\uc740 \ubcf5\uc7a1\ud55c \uc124\uc815 \ubc29\uc2dd\uc744 \ubc14\uafb8\uace0\uc790 Flat Config\ub77c\ub294 \uc0c8\ub85c\uc6b4 \uc124\uc815 \ubc29\uc2dd\uc744 \ub3c4\uc785\ud588\uace0, \ud3ec\ub9e4\ud305 \ub8f0\uc744 \uc720\uc9c0\ubcf4\uc218\ud558\ub294\ub370\uc5d0 \uc5b4\ub824\uc6c0\uc744 \ud1a0\ub300\ub85c \ud3ec\ub9e4\ud305 \ub8f0\uc744 \ub77c\uc774\ube0c\ub7ec\ub9ac\ud654\ud588\uc2b5\ub2c8\ub2e4. \ud3ec\ub9e4\ud305 \ub8f0\uc740 <a href=\\"https://ones-to-watch.ethansup.net/news/post/dac588d9-f575-4eef-b830-f21f1c3fb35d#bff46218-8354-4aa8-be1f-765f4606c54a\\">\uc911\ubcf5\uc73c\ub85c \uc18c\uac1c</a>\ub4dc\ub9ac\ubbc0\ub85c \uc774\uc804 \uae00\uc744 \ubcf4\ub294 \uac83\ub3c4 \uc88b\uc2b5\ub2c8\ub2e4!</p><h2 data-notion-block-id=\\"959d70c7-fc29-4f14-a0aa-498e0752c81e\\" id=\\"959d70c7-fc29-4f14-a0aa-498e0752c81e\\">RN 0.74 \ucd9c\uc2dc</h2><a href=\\"https://reactnative.dev/blog/2024/04/22/release-0.74\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://reactnative.dev/blog/2024/04/22/release-0.74</a><p data-notion-block-id=\\"bf5824f4-6d6d-458b-86ca-1f11a496fb7c\\">\uc0c8\ub85c\uc6b4 \uc544\ud0a4\ud14d\uccd0\ub97c \uc0ac\uc6a9\ud558\ub294 \ubc11\uac70\ub984\uc778 bridgeless \ubaa8\ub4dc\uac00 \uae30\ubcf8 \uc124\uc815\uc73c\ub85c \ub418\uace0, \ub808\uc774\uc544\uc6c3 \uc5d4\uc9c4\uc778 Yoga\uac00 \uc5c5\ub370\uc774\ud2b8\ub418\uc5c8\ub2e4\ub294 \uc18c\uc2dd\uc785\ub2c8\ub2e4. New architecture\uac00 \uad81\uae08\ud558\uc2e0 \ubd84\uc740 <a href=\\"https://www.youtube.com/watch?v=52El0EUI6D0\\">\ubc1c\ud45c</a>\uc640 <a href=\\"https://www.callstack.com/blog/experiment-with-new-architecture-of-react-native\\">\uc815\ub9ac\uae00</a>\uc744 \ubcf4\uc138\uc694 :)</p><p data-notion-block-id=\\"6b62af79-b30e-4e8f-a9e3-6fa78466c5a3\\"></p>"}')}}]);